# owner: platform
"""Plain text absence notices for parents."""

from rosterkit.attendance import days_missed


def _compose(student, days):
    count = len(days)
    noun = "day" if count == 1 else "days"
    dates = ", ".join(item.isoformat() for item in days)
    return (
        f"{student.first_name} {student.last_name} "
        f"missed {count} {noun} of school: {dates}."
    )


def _foreign(student, marks):
    return any(
        mark.student_id != student.student_id for mark in marks
    )


def absence_notice(student, marks):
    """Build a notice listing the absent days in order."""
    marks = list(marks)
    if _foreign(student, marks):
        raise ValueError("marks belong to another student")
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to report")
    return _compose(student, days)
